for (const [key,url,offs] of [
["lw","https://www.polyu.edu.hk/ama/profile/byli/FoCM-3.pdf",[12000,32000,52000,72000,92000,112000]],
["bit","https://arxiv.org/pdf/0910.1389v2",[28000,64000,84000]]
]) {
