for(let i=0;i<rs.length;i++){const r=rs[i];if(r.status==="fulfilled"){const v=JSON.parse(r.value);store(key+offs[i],v.content);text({key,offset:offs[i],next:v.next_offset,more:v.has_more,content:v.content});}else text(r);}
}

