["lw",[/Proposition 3\.4/g,/Lemma 7\.2/g,/\(4\.15\)/g,/\(4\.20\)/g,/\(4\.23\)/g,/\(5\.2\)/g,/\(6\.1\)/g]],
["bit",[/Theorem 4\.2/g,/Theorem 4\.3/g,/Theorem 5\.1/g,/Theorem 6\.3/g,/Theorem 6\.4/g,/Theorem 6\.5/g]]]){
