for(const off of offs){const s=load(key+off);if(!s)continue;for(const p of patterns){for(const m of s.matchAll(p))text({key,off,match:m.index,excerpt:s.slice(Math.max(0,m.index-250),m.index+4300)});}}
}

for(const [key,off,pat,len] of [["lw",92000,"Lemma 7.2.",4800],["lw",112000,"Lemma 7.2.",3000],["bit",28000,"Theorem 4.2.",6500],["bit",64000,"Theorem 6.3.",1700]]){
const s=load(key+off)||"";const i=s.indexOf(pat);text({key,off,i,text:i<0?"not at this offset":s.slice(i,i+len)});
}
text({lwStageOccurrences:[72000,92000,112000].map(off=>{const s=load("lw"+off)||"";return {off,m:[...s.matchAll(/Lemma 7\.2/g)].map(m=>m.index)}})});

text(load("lw72000").slice(4850,10400));
const s=load("bit28000"); const i=s.indexOf("Theorem 5.1.");text({i,excerpt:i>=0?s.slice(i,i+2600):""});
text(load("lw32000").slice(17400,20000));
text(load("lw52000").slice(0,3900));
const ar=await tools.read_external_source({url:"https://arxiv.org/abs/0910.1389v2",limit:5500});store("bitabs",ar);text(ar);

for(const off of [52000,72000]){const s=load("lw"+off);for(const m of s.matchAll(/Lemma 7\.2/g))text({off,text:s.slice(Math.max(0,m.index-150),m.index+2500)});}
const r=JSON.parse(await tools.read_external_source({url:"https://arxiv.org/pdf/0910.1389v2",offset:42000,limit:22000}));store("bit42000",r.content);
const i=r.content.indexOf("Theorem 5.1.");text({i,text:r.content.slice(i,i+3500)});
text(load("lw72000").slice(0,1500));
