const r=JSON.parse(await tools.read_task_input({id:"target-selection.json",pointer:"/full_target"}));store("fullTarget",r.value);text({stored:typeof r.value});
const law=await tools.read_yui({path:"nl0/templates/authoring.md",start:1,end:220});text(law);
const v=load("lw52000"); const i=v.indexOf("Lemma 7.2. For");store("stageSource",v.slice(i,v.indexOf("Proof.",i))); 
