text(await tools.read_external_source({url:"https://doi.org/10.1007/s10208-025-09702-0",limit:6500}));

const mk=(symbol,type)=>({symbol,type});
const D=[];
function def(id,symbol,type,definition,depends_on=[],binders=[],objects=[],requires=[]){D.push({id,symbol,type,definition,depends_on,requires,binders,objects});}
def("D001","Ttor","periodic measured domain","Ttor = R/(2*pi*Z), with normalized measure dx/(2*pi); spatial products and integrals are on this domain.");
def("D002","Fourier","Fourier coefficient transform","For an integrable periodic f, Fourier(f)(k)=hat f(k)=(2*pi)^(-1) integral_0^(2*pi) f(x) exp(-i*k*x) dx; the transform extends to distributions by duality.",["D001"],[mk("f","periodic distribution"),mk("k","integer")],["Ttor","f","k"]);
def("D003","H","family of periodic Sobolev spaces","For every real s, H^s(Ttor) is the completion of trigonometric polynomials with ||f||_(H^s)^2=sum_(k in Z) <k>^(2*s)|hat f(k)|^2, <k>=(1+k^2)^(1/2). Negative spaces are interpreted as distributions. Homogeneous norms on zero-mean distributions are ||f||_(dot H^s)^2=sum_(k!=0)|k|^(2*s)|hat f(k)|^2. Real means hat f(-k)=conjugate(hat f(k)); mean zero means hat f(0)=0.",["D001","D002"],[mk("s","real"),mk("f","periodic distribution")],["Ttor","Fourier","s","f"]);
def("D004","L2","normalized Hilbert space and norm","L2=H^0(Ttor), with ||f||_2^2=(2*pi)^(-1) integral |f|^2 dx. More generally L^p uses the same normalized measure; L^infinity is essential supremum. Sequence ell^2 uses counting measure on Z (or Z\\{0} when specified). Time suprema use continuous representatives; derivative norms are essential suprema.",["D001","D003"],[],["Ttor","H"]);
def("D005","S","Airy group indexed by real time","S_t=exp(-t*partial_x^3), hat(S_t f)(k)=exp(i*t*k^3) hat f(k).",["D002","D003"],[mk("t","real"),mk("f","periodic distribution")],["Fourier","H","t","f"]);
def("D006","P0","spatial mean projection","P0(f)=hat f(0), identified with a constant function.",["D002"],[mk("f","periodic distribution")],["Fourier","f"]);
def("D007","Pnz","projection onto nonzero modes","Pnz=I-P0, denoted P in the supplied proof. Fourier projections P_leq(N) and P_gt(N) retain |k|<=N and |k|>N respectively, for N>=0.",["D002","D006"],[mk("N","nonnegative real")],["Fourier","P0","N"]);
def("D008","Dinv","inverse derivative and its square","Dinv=partial_x^(-1) has Fourier multiplier (i*k)^(-1) at nonzero integer k and zero at k=0. Dinv2=(Dinv)^2 is denoted D^(-2).",["D002"],[],["Fourier"]);
def("D009","Ftau","quadratic update family for positive timestep","For tau>0 and mean-zero f in L2, Ftau(f)=(1/6)*Pnz[(S_tau Dinv f)^2]-(1/6)*S_tau Pnz[(Dinv f)^2].",["D004","D005","D007","D008"],[mk("tau","positive real"),mk("f","mean-zero L2 function")],["S","Pnz","Dinv","L2","tau","f"]);
def("D010","Htau","cubic update family for positive timestep","For tau>0 and mean-zero f in L2, Htau(f)=(1/3)*Pnz[(S_tau Dinv f)*Dinv Ftau(f)]+(tau/9)*(S_tau Dinv f)*P0(f^2)-(1/54)*[S_(tau-s) Dinv[(S_s Dinv f)^3]]_(s=0)^(s=tau)-(1/(27*tau))*[S_(tau-s) Dinv2[(S_(s-tau) Dinv2 Ftau(f))*(S_s Dinv f)]]_(s=0)^(s=tau). Brackets mean the value at tau minus the value at zero. All products are spatial products.",["D004","D005","D006","D007","D008","D009"],[mk("tau","positive real"),mk("f","mean-zero L2 function")],["L2","S","P0","Pnz","Dinv","Ftau","tau","f"]);
def("D011","Psi","unfiltered numerical update and iterates","Psi_tau(f)=S_tau f+Ftau(f)+Htau(f). Given mean-zero u0 in L2 and an integer L>=1, set tau=T/L, t_n=n*tau, u^0=u0 and u^(n+1)=Psi_tau(u^n) for 0<=n<L; write v^n=S_(-t_n)u^n. There is no spatial cutoff.",["D004","D005","D009","D010"],[mk("tau","positive real"),mk("f","mean-zero L2 function"),mk("u0","mean-zero L2 function"),mk("L","positive integer")],["T","S","L2","Ftau","Htau","tau","f","u0","L"]);
def("D012","KdV","equation and exact-solution convention","KdV is u_t+u_xxx=(1/2)*partial_x(u^2), u(0)=u0. An exact solution on [0,T] with H^gamma data means the unique real mean-zero C([0,T];H^gamma(Ttor)) distributional solution obtained by smooth approximation. This describes the convention and asserts no existence. For such a solution write v(t)=S_(-t)u(t), and M=1+sup_[0,T]||v(t)||_(H^gamma).",["D001","D003","D005"],[mk("u","time-dependent periodic distribution"),mk("u0","periodic distribution")],["T","gamma","Ttor","H","S","u","u0"]);
def("D013","eta","average covariance","For tau>0 and real alpha,beta, M_tau g=tau^(-1) integral_0^tau g(s) ds and eta_tau(alpha,beta)=M_tau(exp(-i*s*(alpha+beta)))-M_tau(exp(-i*s*alpha))*M_tau(exp(-i*s*beta)).",[],[mk("tau","positive real"),mk("alpha","real"),mk("beta","real")],["tau","alpha","beta"]);
def("D014","Remainder","averaged cubic trilinear Fourier family, initially on polynomials","For tau>0, t0 real, and mean-zero polynomial inputs f1,f2,f3, define Remainder_(t0,tau)(f1,f2,f3) to have zero mean and, for k!=0, Fourier coefficient -tau/(18*i*k) sum_(a+b+c=k,a+b!=0) exp(-i*t0*Phi)*eta_tau(alpha,beta)*hat f1(a)*hat f2(b)*hat f3(c), where p=a+b, alpha=3*a*b*p, beta=3*k*c*p and Phi=alpha+beta=k^3-a^3-b^3-c^3. Its bounded extensions will be proved; R^n_(2,tau) means t0=t_n.",["D002","D013"],[mk("tau","positive real"),mk("t0","real"),mk("f1","mean-zero polynomial"),mk("f2","mean-zero polynomial"),mk("f3","mean-zero polynomial")],["Fourier","eta","tau","t0","f1","f2","f3"]);
